-- Materiales del Módulo 2.1
INSERT INTO module_materials (id, module_id, title, content, type, order_index) VALUES
(10008, 1005,
  '{"es":"Observar, preguntar, investigar","en":"Observe, question, research","pt":"Observar, perguntar, pesquisar"}'::jsonb,
  '{"es":"<h2>Del territorio a la pregunta STEM</h2><p>Un buen proyecto STEM nace de una <strong>observación real</strong> en el territorio. El proceso es:</p><h3>1. Observar</h3><p>Visita un lugar cercano a tu escuela y anota todo lo que llame tu atención:</p><ul><li>¿Qué ves que no esperabas?</li><li>¿Qué ha cambiado respecto al año pasado?</li><li>¿Qué problemas identificas?</li></ul><h3>2. Preguntar</h3><p>Transforma tus observaciones en preguntas STEM:</p><ul><li>Observación: «El río tiene menos agua que antes» → Pregunta: «¿Cuánto ha disminuido el caudal del río en los últimos 5 años y qué factores lo explican?»</li><li>Observación: «Hay menos pájaros en el bosque» → Pregunta: «¿Qué relación existe entre la pérdida de cobertura vegetal y la diversidad de aves?»</li><li>Observación: «Los agricultores pierden cosechas» → Pregunta: «¿Cómo podemos diseñar un sistema de alerta temprana de heladas usando sensores?»</li></ul><h3>3. Filtrar</h3><p>Una buena pregunta STEM para un proyecto escolar debe ser:</p><ul><li>✅ <strong>Investigable</strong> por estudiantes con recursos disponibles</li><li>✅ <strong>Medible</strong> con datos recolectables</li><li>✅ <strong>Relevante</strong> para la comunidad local</li><li>✅ <strong>Alineada</strong> al currículo del nivel</li></ul>","en":"<h2>From territory to STEM question</h2><p>A good STEM project starts from a <strong>real observation</strong> in the territory.</p><h3>1. Observe</h3><p>Visit a place near your school and note everything that catches your attention.</p><h3>2. Question</h3><p>Transform observations into STEM questions:</p><ul><li>Observation: \"The river has less water\" → Question: \"How much has the river flow decreased in the last 5 years?\"</li><li>Observation: \"Fewer birds in the forest\" → Question: \"What relationship exists between vegetation loss and bird diversity?\"</li></ul><h3>3. Filter</h3><p>A good school STEM question must be:</p><ul><li>✅ <strong>Researchable</strong> by students</li><li>✅ <strong>Measurable</strong> with collectable data</li><li>✅ <strong>Relevant</strong> to local community</li><li>✅ <strong>Aligned</strong> to grade curriculum</li></ul>","pt":"<h2>Do território à pergunta STEM</h2><p>Um bom projeto STEM nasce de uma <strong>observação real</strong> no território.</p><h3>1. Observar</h3><p>Visite um lugar perto da sua escola e anote tudo que chame sua atenção.</p><h3>2. Perguntar</h3><p>Transforme observações em perguntas STEM:</p><ul><li>Observação: \"O rio tem menos água\" → Pergunta: \"Quanto diminuiu a vazão do rio nos últimos 5 anos?\"</li><li>Observação: \"Menos pássaros na floresta\" → Pergunta: \"Que relação existe entre perda de vegetação e diversidade de aves?\"</li></ul><h3>3. Filtrar</h3><p>Uma boa pergunta STEM escolar deve ser:</p><ul><li>✅ <strong>Investigável</strong> por estudantes</li><li>✅ <strong>Mensurável</strong> com dados coletáveis</li><li>✅ <strong>Relevante</strong> para a comunidade local</li><li>✅ <strong>Alinhada</strong> ao currículo do nível</li></ul>"}'::jsonb,
  'text', 1),
(10009, 1006,
  '{"es":"Anatomía de un proyecto STEM","en":"Anatomy of a STEM project","pt":"Anatomia de um projeto STEM"}'::jsonb,
  '{"es":"<h2>Componentes de un proyecto STEM territorial</h2><p>Todo proyecto STEM en AprendeLocal sigue esta estructura:</p><h3>1. Contexto territorial</h3><p>¿Dónde ocurre? ¿Qué problema local aborda? ¿Por qué importa para la comunidad?</p><h3>2. Objetivos de aprendizaje</h3><p>¿Qué OA del currículo cubre? Debe incluir al menos 2 áreas STEM.</p><h3>3. Materiales y recursos</h3><p>Lista concreta de lo que se necesita. Prioriza materiales accesibles y de bajo costo.</p><h3>4. Sesiones de trabajo</h3><p>Divididas en fases claras:</p><ul><li><strong>Sesión 1:</strong> Exploración del lugar y formulación de preguntas</li><li><strong>Sesiones 2-3:</strong> Recolección de datos y experimentación</li><li><strong>Sesión 4:</strong> Análisis y conexión con teoría</li><li><strong>Sesión 5:</strong> Producto final y presentación a la comunidad</li></ul><h3>5. Productos esperados</h3><p>Tangibles: informe, maqueta, prototipo, mapa, presentación, propuesta al municipio.</p><h3>6. Rúbrica de evaluación</h3><p>Evalúa proceso (colaboración, investigación) y producto (calidad, impacto, alineación curricular).</p>","en":"<h2>Components of a territorial STEM project</h2><h3>1. Territorial context</h3><p>Where does it happen? What local problem does it address?</p><h3>2. Learning objectives</h3><p>Which curriculum objectives does it cover? Must include at least 2 STEM areas.</p><h3>3. Materials and resources</h3><p>Concrete list. Prioritize accessible, low-cost materials.</p><h3>4. Work sessions</h3><ul><li><strong>Session 1:</strong> Place exploration and question formulation</li><li><strong>Sessions 2-3:</strong> Data collection and experimentation</li><li><strong>Session 4:</strong> Analysis and theory connection</li><li><strong>Session 5:</strong> Final product and community presentation</li></ul><h3>5. Expected products</h3><p>Report, model, prototype, map, presentation, municipal proposal.</p><h3>6. Assessment rubric</h3><p>Evaluates process (collaboration, research) and product (quality, impact, alignment).</p>","pt":"<h2>Componentes de um projeto STEM territorial</h2><h3>1. Contexto territorial</h3><p>Onde acontece? Que problema local aborda?</p><h3>2. Objetivos de aprendizagem</h3><p>Quais objetivos do currículo cobre? Deve incluir pelo menos 2 áreas STEM.</p><h3>3. Materiais e recursos</h3><p>Lista concreta. Priorize materiais acessíveis e de baixo custo.</p><h3>4. Sessões de trabalho</h3><ul><li><strong>Sessão 1:</strong> Exploração do lugar e formulação de perguntas</li><li><strong>Sessões 2-3:</strong> Coleta de dados e experimentação</li><li><strong>Sessão 4:</strong> Análise e conexão com teoria</li><li><strong>Sessão 5:</strong> Produto final e apresentação à comunidade</li></ul><h3>5. Produtos esperados</h3><p>Relatório, maquete, protótipo, mapa, apresentação, proposta ao município.</p><h3>6. Rubrica de avaliação</h3><p>Avalia processo (colaboração, pesquisa) e produto (qualidade, impacto, alinhamento).</p>"}'::jsonb,
  'text', 1),
(10010, 1007,
  '{"es":"Genera proyectos con la Plataforma STEM","en":"Generate projects with the STEM Platform","pt":"Gere projetos com a Plataforma STEM"}'::jsonb,
  '{"es":"<h2>La Plataforma STEM de AprendeLocal</h2><p>AprendeLocal incluye una herramienta de IA que genera proyectos STEM automáticamente para tu zona. Así funciona:</p><h3>Paso 1: Selecciona tu escuela</h3><p>En el mapa de la Plataforma STEM (<code>/plataforma</code>), busca tu escuela por nombre o navega el mapa de La Araucanía.</p><h3>Paso 2: Explora puntos de interés</h3><p>El sistema muestra puntos de interés educativos cercanos a tu escuela: parques nacionales, volcanes, ríos, humedales, sitios patrimoniales.</p><h3>Paso 3: Genera el proyecto</h3><p>Selecciona un punto de interés y haz clic en «Generar proyecto STEM». La IA de Claude analiza:</p><ul><li>El ecosistema y características del lugar</li><li>Las amenazas y oportunidades ambientales</li><li>El nivel educativo seleccionado</li><li>Los Objetivos de Aprendizaje del currículo chileno</li></ul><p>Y genera un proyecto completo con objetivos, materiales, sesiones y rúbrica.</p><h3>Paso 4: Personaliza</h3><p>El proyecto generado es un <strong>punto de partida</strong>. Adáptalo a tu realidad: ajusta tiempos, materiales y complejidad según tus estudiantes.</p><h3>Paso 5: Comparte con estudiantes</h3><p>Genera un código de acceso para que tus estudiantes se unan al proyecto. Ellos pueden registrar su progreso, notas de campo y quiz directamente en la plataforma.</p>","en":"<h2>AprendeLocal''s STEM Platform</h2><p>AprendeLocal includes an AI tool that automatically generates STEM projects for your area.</p><h3>Step 1: Select your school</h3><p>On the STEM Platform map (<code>/plataforma</code>), find your school by name or navigate the La Araucanía map.</p><h3>Step 2: Explore points of interest</h3><p>The system shows nearby educational points of interest: national parks, volcanoes, rivers, wetlands, heritage sites.</p><h3>Step 3: Generate the project</h3><p>Select a point of interest and click \"Generate STEM project.\" Claude''s AI analyzes the ecosystem, threats, educational level, and curriculum objectives to generate a complete project.</p><h3>Step 4: Customize</h3><p>The generated project is a <strong>starting point</strong>. Adapt it to your reality.</p><h3>Step 5: Share with students</h3><p>Generate an access code so students can join the project and track their progress.</p>","pt":"<h2>A Plataforma STEM da AprendeLocal</h2><p>A AprendeLocal inclui uma ferramenta de IA que gera projetos STEM automaticamente para sua região.</p><h3>Passo 1: Selecione sua escola</h3><p>No mapa da Plataforma STEM (<code>/plataforma</code>), busque sua escola por nome ou navegue o mapa da Araucanía.</p><h3>Passo 2: Explore pontos de interesse</h3><p>O sistema mostra pontos de interesse educativos próximos: parques nacionais, vulcões, rios, áreas úmidas, sítios patrimoniais.</p><h3>Passo 3: Gere o projeto</h3><p>Selecione um ponto de interesse e clique em \"Gerar projeto STEM\". A IA do Claude analisa o ecossistema, ameaças, nível educativo e objetivos curriculares para gerar um projeto completo.</p><h3>Passo 4: Personalize</h3><p>O projeto gerado é um <strong>ponto de partida</strong>. Adapte à sua realidade.</p><h3>Passo 5: Compartilhe com estudantes</h3><p>Gere um código de acesso para que seus estudantes participem do projeto e registrem seu progresso.</p>"}'::jsonb,
  'text', 1)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, type = EXCLUDED.type, order_index = EXCLUDED.order_index;


