-- Materiales del Módulo 3.1: Primeros pasos
INSERT INTO module_materials (id, module_id, title, content, type, order_index) VALUES
(10011, 1008,
  '{"es":"Crear tu cuenta","en":"Create your account","pt":"Criar sua conta"}'::jsonb,
  '{"es":"<h2>Bienvenido a AprendeLocal</h2><p>AprendeLocal es una plataforma de educación STEM que conecta el aprendizaje con tu territorio local. Esta guía te mostrará cómo usar cada función.</p><h3>Crear una cuenta</h3><ol><li>Ve a <strong>aprendelocal.com</strong></li><li>Haz clic en <strong>«Entrar»</strong> en la esquina superior derecha</li><li>Si no tienes cuenta, haz clic en <strong>«Registrarse»</strong></li><li>Completa: nombre, correo electrónico, contraseña y código postal</li><li>Haz clic en <strong>«Registrar»</strong></li><li>Inicia sesión con tu correo y contraseña</li></ol><h3>Navegación principal</h3><p>Una vez dentro, verás la barra de navegación con estas opciones:</p><ul><li><strong>Inicio:</strong> Landing page con el mini-juego interactivo y accesos rápidos</li><li><strong>Cursos:</strong> Catálogo de cursos disponibles (el que estás usando ahora)</li><li><strong>Perfil:</strong> Tu información, badges y cursos activos</li><li><strong>Plataforma STEM:</strong> Herramienta de mapa y generación de proyectos (requiere login)</li></ul><h3>Idioma</h3><p>AprendeLocal está disponible en <strong>español, inglés y portugués</strong>. Cambia el idioma con el selector <strong>ES / EN / PT</strong> en la esquina superior derecha.</p>","en":"<h2>Welcome to AprendeLocal</h2><p>AprendeLocal is a STEM education platform that connects learning with your local territory.</p><h3>Create an account</h3><ol><li>Go to <strong>aprendelocal.com</strong></li><li>Click <strong>\"Sign in\"</strong> in the top right corner</li><li>If you don''t have an account, click <strong>\"Register\"</strong></li><li>Fill in: name, email, password, and ZIP code</li><li>Click <strong>\"Register\"</strong></li><li>Sign in with your email and password</li></ol><h3>Main navigation</h3><ul><li><strong>Home:</strong> Landing page with interactive mini-game</li><li><strong>Courses:</strong> Course catalog</li><li><strong>Profile:</strong> Your info, badges, and active courses</li><li><strong>STEM Platform:</strong> Map tool and project generation</li></ul><h3>Language</h3><p>Available in <strong>Spanish, English, and Portuguese</strong>. Change with the ES/EN/PT selector.</p>","pt":"<h2>Bem-vindo à AprendeLocal</h2><p>A AprendeLocal é uma plataforma de educação STEM que conecta a aprendizagem ao seu território local.</p><h3>Criar uma conta</h3><ol><li>Acesse <strong>aprendelocal.com</strong></li><li>Clique em <strong>\"Entrar\"</strong> no canto superior direito</li><li>Se não tem conta, clique em <strong>\"Registrar-se\"</strong></li><li>Preencha: nome, e-mail, senha e CEP</li><li>Clique em <strong>\"Registrar\"</strong></li><li>Faça login com seu e-mail e senha</li></ol><h3>Navegação principal</h3><ul><li><strong>Início:</strong> Landing page com mini-jogo interativo</li><li><strong>Cursos:</strong> Catálogo de cursos</li><li><strong>Perfil:</strong> Suas informações, badges e cursos ativos</li><li><strong>Plataforma STEM:</strong> Ferramenta de mapa e geração de projetos</li></ul><h3>Idioma</h3><p>Disponível em <strong>espanhol, inglês e português</strong>. Mude com o seletor ES/EN/PT.</p>"}'::jsonb,
  'text', 1),
(10012, 1009,
  '{"es":"Explorar y tomar cursos","en":"Explore and take courses","pt":"Explorar e fazer cursos"}'::jsonb,
  '{"es":"<h2>Sistema de cursos</h2><h3>Catálogo de cursos</h3><p>En la página <strong>Cursos</strong> (<code>/cursos</code>) encontrarás todos los cursos disponibles. Cada tarjeta muestra:</p><ul><li>Imagen del curso</li><li>Categoría (Formación Docente, Plataforma, STEM)</li><li>Nivel (Introductorio, Intermedio, Avanzado)</li><li>Estado: <strong>Nuevo</strong>, <strong>En progreso</strong> o <strong>Completado</strong></li></ul><h3>Tomar un curso</h3><ol><li>Haz clic en un curso para abrirlo</li><li>Verás el <strong>sidebar</strong> con los módulos y materiales</li><li>El material actual se muestra en el panel principal</li><li>Lee el contenido y haz clic en <strong>«Marcar como completado»</strong></li><li>El siguiente material se desbloqueará automáticamente</li></ol><h3>Progreso</h3><p>Tu progreso se guarda automáticamente. Puedes salir y volver en cualquier momento — el sistema recordará dónde quedaste.</p><p>La barra de progreso en la parte superior muestra cuántos materiales has completado.</p><h3>Badges</h3><p>Al completar un curso, recibes un <strong>badge</strong> (insignia). Los badges aparecen en tu perfil y representan tus logros.</p><h3>Tutor IA</h3><p>Dentro de cada material verás un panel de <strong>Tutor IA</strong>. Puedes hacerle preguntas sobre el contenido que estás leyendo y te responderá basándose exclusivamente en ese material.</p>","en":"<h2>Course system</h2><h3>Course catalog</h3><p>On the <strong>Courses</strong> page (<code>/cursos</code>) you''ll find all available courses. Each card shows image, category, level, and status.</p><h3>Taking a course</h3><ol><li>Click a course to open it</li><li>The sidebar shows modules and materials</li><li>Read content and click <strong>\"Mark as completed\"</strong></li><li>The next material unlocks automatically</li></ol><h3>Progress</h3><p>Your progress saves automatically. You can leave and return anytime.</p><h3>Badges</h3><p>Complete a course to earn a badge, visible on your profile.</p><h3>AI Tutor</h3><p>Inside each material, you can ask the AI tutor questions about the content.</p>","pt":"<h2>Sistema de cursos</h2><h3>Catálogo de cursos</h3><p>Na página <strong>Cursos</strong> (<code>/cursos</code>) você encontrará todos os cursos disponíveis.</p><h3>Fazer um curso</h3><ol><li>Clique em um curso para abri-lo</li><li>A sidebar mostra módulos e materiais</li><li>Leia o conteúdo e clique em <strong>\"Marcar como concluído\"</strong></li><li>O próximo material é desbloqueado automaticamente</li></ol><h3>Progresso</h3><p>Seu progresso é salvo automaticamente.</p><h3>Badges</h3><p>Complete um curso para ganhar um badge, visível no seu perfil.</p><h3>Tutor IA</h3><p>Dentro de cada material, você pode perguntar ao tutor IA sobre o conteúdo.</p>"}'::jsonb,
  'text', 1),
(10013, 1010,
  '{"es":"Usar la Plataforma STEM","en":"Using the STEM Platform","pt":"Usar a Plataforma STEM"}'::jsonb,
  '{"es":"<h2>Plataforma STEM: tu laboratorio territorial</h2><p>La Plataforma STEM (<code>/plataforma</code>) es la herramienta principal para docentes en Chile. Te permite explorar tu territorio y generar proyectos STEM con IA.</p><h3>El mapa</h3><p>Al entrar verás un mapa de La Araucanía con:</p><ul><li>🏫 <strong>Escuelas rurales</strong> (puntos azules)</li><li>🌲 <strong>Puntos de interés</strong> (puntos verdes): parques, volcanes, humedales, sitios culturales</li></ul><p>Haz clic en una escuela para ver los puntos de interés cercanos.</p><h3>Generar un proyecto</h3><ol><li>Selecciona un <strong>punto de interés</strong> cercano a tu escuela</li><li>Elige el <strong>nivel educativo</strong> (5to básico a 2do medio)</li><li>Opcionalmente selecciona <strong>Objetivos de Aprendizaje</strong> específicos</li><li>Haz clic en <strong>«Generar proyecto STEM»</strong></li><li>La IA genera un proyecto completo en 15-30 segundos</li></ol><h3>Expandir el proyecto</h3><p>Una vez generado, haz clic en <strong>«Expandir»</strong> para obtener:</p><ul><li>Sesiones detalladas con actividades</li><li>Guía docente</li><li>Fichas de trabajo para estudiantes</li><li>Rúbrica de evaluación</li></ul><h3>Compartir con estudiantes</h3><ol><li>Haz clic en <strong>«Compartir»</strong> para generar un código</li><li>Comparte el código con tus estudiantes (ej: <code>AKM47R</code>)</li><li>Los estudiantes ingresan el código para unirse al proyecto</li><li>Pueden registrar progreso, notas de campo y responder quizzes</li></ol><h3>Panel de seguimiento</h3><p>Como docente, puedes ver el progreso de todos tus estudiantes en un dashboard con porcentaje de avance, notas de campo y resultados de quizzes.</p>","en":"<h2>STEM Platform: your territorial lab</h2><p>The STEM Platform (<code>/plataforma</code>) is the main tool for teachers in Chile.</p><h3>The map</h3><p>You''ll see a La Araucanía map with schools (blue) and points of interest (green).</p><h3>Generate a project</h3><ol><li>Select a point of interest near your school</li><li>Choose educational level</li><li>Optionally select specific Learning Objectives</li><li>Click \"Generate STEM project\"</li><li>AI generates a complete project in 15-30 seconds</li></ol><h3>Expand and share</h3><p>Expand for detailed sessions, teacher guide, worksheets, and rubric. Share with a code for students to join.</p>","pt":"<h2>Plataforma STEM: seu laboratório territorial</h2><p>A Plataforma STEM (<code>/plataforma</code>) é a ferramenta principal para professores no Chile.</p><h3>O mapa</h3><p>Você verá um mapa da Araucanía com escolas (azul) e pontos de interesse (verde).</p><h3>Gerar um projeto</h3><ol><li>Selecione um ponto de interesse perto da sua escola</li><li>Escolha o nível educativo</li><li>Opcionalmente selecione Objetivos de Aprendizagem específicos</li><li>Clique em \"Gerar projeto STEM\"</li><li>A IA gera um projeto completo em 15-30 segundos</li></ol><h3>Expandir e compartilhar</h3><p>Expanda para sessões detalhadas, guia docente, fichas e rubrica. Compartilhe com um código para estudantes participarem.</p>"}'::jsonb,
  'text', 1),
(10014, 1011,
  '{"es":"Perfil, comunidades y personalización","en":"Profile, communities, and customization","pt":"Perfil, comunidades e personalização"}'::jsonb,
  '{"es":"<h2>Tu espacio personal</h2><h3>Perfil</h3><p>En <strong>Perfil</strong> (<code>/perfil</code>) puedes:</p><ul><li>Ver y editar tu información personal</li><li>Cambiar tu avatar (elige entre el catálogo de avatares)</li><li>Ver tus <strong>badges</strong> obtenidos al completar cursos</li><li>Revisar tus <strong>cursos activos</strong> y continuar donde quedaste</li><li>Ver tus <strong>comunidades</strong></li></ul><h3>Comunidades</h3><p>En <strong>Comunidades</strong> (<code>/comunidades</code>) puedes:</p><ul><li>Explorar comunidades existentes</li><li>Unirte a comunidades que te interesen</li><li>Ver los miembros de cada comunidad</li><li>Filtrar entre «Todas» y «Las mías»</li></ul><p>Las comunidades son espacios para conectar con otros docentes y estudiantes de tu zona.</p><h3>Idioma y accesibilidad</h3><ul><li>Cambia el idioma con el selector <strong>ES / EN / PT</strong> en el header</li><li>En móvil, abre el menú hamburguesa (☰) para acceder a todas las opciones</li><li>La plataforma se adapta a pantallas de escritorio, tablet y celular</li></ul><h3>¡Listo!</h3><p>Ya conoces todas las herramientas de AprendeLocal. Explora los cursos de <strong>Aprendizaje Basado en el Lugar</strong> y <strong>Diseño de Proyectos STEM</strong> para profundizar en la metodología. ¡Buen viaje maker!</p>","en":"<h2>Your personal space</h2><h3>Profile</h3><p>In <strong>Profile</strong> (<code>/perfil</code>) you can view/edit your info, change avatar, see badges and active courses.</p><h3>Communities</h3><p>In <strong>Communities</strong> (<code>/comunidades</code>) explore and join communities to connect with other teachers.</p><h3>Language</h3><p>Change language with the ES/EN/PT selector. The platform adapts to desktop, tablet, and mobile.</p><h3>Ready!</h3><p>You now know all AprendeLocal tools. Explore the Place-Based Learning and STEM Project Design courses to deepen the methodology!</p>","pt":"<h2>Seu espaço pessoal</h2><h3>Perfil</h3><p>Em <strong>Perfil</strong> (<code>/perfil</code>) você pode ver/editar suas informações, mudar avatar, ver badges e cursos ativos.</p><h3>Comunidades</h3><p>Em <strong>Comunidades</strong> (<code>/comunidades</code>) explore e participe de comunidades para conectar com outros professores.</p><h3>Idioma</h3><p>Mude o idioma com o seletor ES/EN/PT. A plataforma se adapta a desktop, tablet e celular.</p><h3>Pronto!</h3><p>Agora você conhece todas as ferramentas da AprendeLocal. Explore os cursos de Aprendizagem Baseada no Lugar e Design de Projetos STEM para aprofundar a metodologia!</p>"}'::jsonb,
  'text', 1)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content, type = EXCLUDED.type, order_index = EXCLUDED.order_index;

